function toPost(filter, ch, index) {
  return {
    title: ch[0],
    image: ch[1],
    link: 'freetv|' + filter + '|' + index,
    tag: 'Live'
  };
}

async function getPosts(args) {
  var filter = (args && args.filter) || 'all';
  if (!DATA.hasOwnProperty(filter)) filter = 'all';
  var page = Math.max(1, parseInt((args && args.page) || '1', 10) || 1);
  var channels = DATA[filter];
  var start = (page - 1) * PAGE_SIZE;
  return channels.slice(start, start + PAGE_SIZE).map(function (ch, i) {
    return toPost(filter, ch, start + i);
  });
}

async function getSearchPosts(args) {
  var q = String((args && args.searchQuery) || '').trim().toLowerCase();
  if (!q) return [];
  var channels = DATA.all;
  var hits = [];
  for (var i = 0; i < channels.length && hits.length < 40; i++) {
    if (channels[i][0].toLowerCase().indexOf(q) !== -1) hits.push(toPost('all', channels[i], i));
  }
  return hits;
}

// CommonJS exports for the unictoos sandbox (exact export names matter).
if (typeof module !== 'undefined' && module.exports) {
  module.exports.getPosts = getPosts;
  module.exports.getSearchPosts = getSearchPosts;
}
